const $ = id => document.getElementById(id);
function safe(s) { return String(s).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])); }
function renderTiles(id, items) {
  $(id).innerHTML = items.map(([title,sub,icon,cat]) => `<button class="tile" data-cat="${safe(cat)}" data-search="${safe(title+" "+sub)}"><span class="tile-icon">${icon}</span><span class="tile-title">${safe(title)}</span><span class="tile-sub">${safe(sub)}</span><span class="tile-label">OPEN DIRECTORY ↗</span></button>`).join("");
  $(id).querySelectorAll(".tile").forEach(el=>el.addEventListener("click",()=>{activeCategory=el.dataset.cat;query=el.dataset.search.split(" ")[0];$("search").value=query;renderCategories();renderServices();$("services").scrollIntoView({behavior:"smooth"});}));
}
function renderCategories() {
 const names=["ALL CATEGORIES","KAR GOVT. SERVICES","CENTRAL GOVT","OTHER SERVICES",...catalog.map(c=>c.name)];
 $("filters").innerHTML=[...new Set(names)].map(n=>`<button class="filter ${activeCategory===n?"active":""}" data-name="${safe(n)}">${safe(n)}</button>`).join("");
 $("filters").querySelectorAll("button").forEach(b=>b.onclick=()=>{activeCategory=b.dataset.name;renderCategories();renderServices();});
}
function renderServices() {
 let list=allServices.filter(s=>(activeCategory==="ALL CATEGORIES"||activeCategory==="OTHER SERVICES"||activeCategory==="CENTRAL GOVT"||activeCategory==="KAR GOVT. SERVICES"||s.category===activeCategory)&&(!query||(s.name+" "+s.category).toLowerCase().includes(query.toLowerCase())));
 if(activeCategory==="CENTRAL GOVT") list=list.filter(s=>/central|india|aadhaar|pan|epfo|pf|passport|gst|pm-|abha|ayushman|eshram|scholarship|apaar|digilocker/i.test(s.name+" "+s.category));
 if(activeCategory==="KAR GOVT. SERVICES") list=list.filter(s=>/karnataka|nadakacheri|fruits|yuvanidhi|ksrtc|swalambi/i.test(s.name+" "+s.category));
 $("resultCount").textContent=`${list.length.toLocaleString("en-IN")} services found`;
 $("serviceList").innerHTML=list.slice(0,220).map(s=>`<button class="service-row" data-name="${safe(s.name)}" data-cat="${safe(s.category)}"><span class="service-icon">▣</span><span><b>${safe(s.name)}</b><small>${safe(s.category)}</small></span><span class="open-arrow">›</span></button>`).join("") || `<div class="empty">No matching service found. Try another search.</div>`;
 $("serviceList").querySelectorAll("button").forEach(b=>b.onclick=()=>showDetails(b.dataset.name,b.dataset.cat));
}
function showDetails(name,cat) {
 $("modalTitle").textContent=name;
 $("modalCategory").textContent=cat;
 $("modalText").textContent="This portal provides service information and guidance. Open the relevant official government portal to check current eligibility, documents, OTP requirements, fees and availability. We do not bypass OTP, collect passwords, or claim unauthorized access.";
 $("serviceModal").showModal();
}
$("search").addEventListener("input",e=>{query=e.target.value.trim();renderServices();});
$("clearSearch").onclick=()=>{$("search").value="";query="";renderServices();};
$("closeModal").onclick=()=>$("serviceModal").close();
renderTiles("quickLinks",quick);renderTiles("trending",trending);renderTiles("newServices",fresh);renderCategories();renderServices();
